#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/*
 * Reimplementation of the original program "prog59_rule110".
 * The binary expects two command‑line arguments:
 *   1. A string consisting only of the characters '0' and '1'.
 *   2. A decimal integer specifying how many generations of the
 *      elementary cellular automaton Rule 110 to output.
 *
 * The program validates its input and prints "INVALID_INPUT" (followed
 * by a newline) on any error.  The length of the initial row must be
 * between 1 and 60 inclusive, and the number of generations is capped
 * at 200.
 *
 * For each generation the program prints the current row (exactly the
 * length of the initial string) followed by a newline, then computes
 * the next row using Rule 110 with a zero‑filled border.
 */

static const unsigned char rule110[8] = {
    /* pattern 111,110,101,100,011,010,001,000 */
    0, 1, 1, 0, 1, 1, 1, 0
};

int main(int argc, char **argv)
{
    if (argc < 3) {
        puts("INVALID_INPUT");
        return 0;
    }

    const char *init = argv[1];
    size_t len = strlen(init);
    if (len == 0 || len > 60) {
        puts("INVALID_INPUT");
        return 0;
    }
    for (size_t i = 0; i < len; ++i) {
        if (init[i] != '0' && init[i] != '1') {
            puts("INVALID_INPUT");
            return 0;
        }
    }

    char *endptr;
    long steps = strtol(argv[2], &endptr, 10);
    if (*endptr != '\0') {
        puts("INVALID_INPUT");
        return 0;
    }
    if (steps < 0) steps = 0;
    if (steps > 200) steps = 200;

    /* store up to 201 rows (initial + up to 200 generations) */
    char rows[201][61];
    memset(rows, '0', sizeof(rows));
    memcpy(rows[0], init, len);
    rows[0][len] = '\0';

    for (int gen = 0; gen < steps; ++gen) {
        /* print current generation */
        for (size_t i = 0; i < len; ++i) {
            putchar(rows[gen][i]);
        }
        putchar('\n');

        /* compute next generation if needed */
        if (gen + 1 < steps) {
            for (size_t i = 0; i < len; ++i) {
                int left  = (i == 0) ? 0 : rows[gen][i - 1] - '0';
                int center = rows[gen][i] - '0';
                int right = (i + 1 == len) ? 0 : rows[gen][i + 1] - '0';
                int pattern = (left << 2) | (center << 1) | right;
                rows[gen + 1][i] = rule110[pattern] + '0';
            }
            rows[gen + 1][len] = '\0';
        }
    }
    return 0;
}
